import { sql } from "drizzle-orm";
import { pgTable, pgEnum, text, uuid, integer, boolean, index, uniqueIndex, primaryKey, timestamp, char, customType } from "drizzle-orm/pg-core";
import { id, createdAt, updatedAt } from "./_shared";

export const productStatus = pgEnum("product_status", [
  "DRAFT", "REVIEW", "SCHEDULED", "PUBLISHED", "ARCHIVED", "DISCONTINUED",
]);

/** Postgres full-text search vector. Generated by the database from name, summary and description (Release 3C). */
const tsvector = customType<{ data: string }>({
  dataType() {
    return "tsvector";
  },
});

export const brands = pgTable("brands", {
  id: id(),
  slug: text("slug").notNull().unique(),
  name: text("name").notNull(),
  description: text("description"),
  logoUrl: text("logo_url"),
  isFeatured: boolean("is_featured").notNull().default(false),
  /** Release 3A: archived brands are hidden but keep their products. Never delete a brand that products use. */
  isActive: boolean("is_active").notNull().default(true),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const categories = pgTable("categories", {
  id: id(),
  parentId: uuid("parent_id"),
  slug: text("slug").notNull().unique(),
  name: text("name").notNull(),
  description: text("description"),
  sortOrder: integer("sort_order").notNull().default(0),
  isActive: boolean("is_active").notNull().default(true),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
}, (t) => [
  index("categories_parent_idx").on(t.parentId),
  /** Release 3A: one category name per parent, ignoring case. Top-level categories share one "no parent" bucket. */
  uniqueIndex("categories_parent_name_uq").on(
    sql`coalesce(${t.parentId}, '00000000-0000-0000-0000-000000000000'::uuid)`,
    sql`lower(${t.name})`,
  ),
]);

export const products = pgTable("products", {
  id: id(),
  slug: text("slug").notNull().unique(),
  name: text("name").notNull(),
  summary: text("summary"),
  description: text("description"),
  brandId: uuid("brand_id").references(() => brands.id, { onDelete: "set null" }),
  status: productStatus("status").notNull().default("DRAFT"),
  publishAt: timestamp("publish_at", { withTimezone: true }),
  isFeatured: boolean("is_featured").notNull().default(false),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
  /**
   * Release 3C: maintained by Postgres, never written by the app. Name weighs most, then summary, then description.
   * Searched with websearch_to_tsquery (see src/modules/catalog/repository.ts).
   */
  searchVector: tsvector("search_vector").generatedAlwaysAs(
    sql`setweight(to_tsvector('english', coalesce(name, '')), 'A') || setweight(to_tsvector('english', coalesce(summary, '')), 'B') || setweight(to_tsvector('english', coalesce(description, '')), 'C')`,
  ),
}, (t) => [
  index("products_status_idx").on(t.status, t.publishAt),
  index("products_brand_idx").on(t.brandId),
  /** Release 3C: full-text search, typo-tolerant name matching (pg_trgm) and the newest-first listing. */
  index("products_search_idx").using("gin", t.searchVector),
  index("products_name_trgm_idx").using("gin", sql`lower(${t.name}) gin_trgm_ops`),
  index("products_listing_idx").on(t.createdAt.desc(), t.id.desc()).where(sql`${t.status} in ('PUBLISHED', 'SCHEDULED')`),
]);

export const productVariants = pgTable("product_variants", {
  id: id(),
  productId: uuid("product_id").notNull().references(() => products.id, { onDelete: "cascade" }),
  sku: text("sku"),
  label: text("label").notNull(),
  priceMinor: integer("price_minor"),
  currency: char("currency", { length: 3 }).notNull().default("INR"),
  /** Release 3B: the order the admin arranged the variants in. */
  sortOrder: integer("sort_order").notNull().default(0),
  createdAt: createdAt(),
}, (t) => [
  index("variants_product_idx").on(t.productId),
  /** Release 3B: a SKU identifies one variant. Variants without a SKU are not constrained. */
  uniqueIndex("variants_sku_uq").on(t.sku).where(sql`${t.sku} is not null`),
  /** Release 3C: the price range filter. */
  index("variants_product_price_idx").on(t.productId, t.currency, t.priceMinor),
]);

export const productImages = pgTable("product_images", {
  id: id(),
  productId: uuid("product_id").notNull().references(() => products.id, { onDelete: "cascade" }),
  publicId: text("public_id").notNull(),
  alt: text("alt").notNull(),
  sortOrder: integer("sort_order").notNull().default(0),
}, (t) => [
  index("images_product_idx").on(t.productId),
  /** Release 3B: images of a product in the order the admin arranged them. */
  index("images_product_order_idx").on(t.productId, t.sortOrder),
  /** Release 3B: "which media is unused" and "where is this image used". */
  index("images_public_id_idx").on(t.publicId),
]);

export const productCategories = pgTable("product_categories", {
  productId: uuid("product_id").notNull().references(() => products.id, { onDelete: "cascade" }),
  categoryId: uuid("category_id").notNull().references(() => categories.id, { onDelete: "cascade" }),
  isPrimary: boolean("is_primary").notNull().default(false),
}, (t) => [
  primaryKey({ columns: [t.productId, t.categoryId] }),
  index("pc_category_idx").on(t.categoryId),
  /** Release 3B: a product has at most one main (primary) category. */
  uniqueIndex("pc_one_primary_uq").on(t.productId).where(sql`${t.isPrimary}`),
  /** Release 3C: "products in these categories" without touching the products table first. */
  index("pc_category_product_idx").on(t.categoryId, t.productId),
]);

export const productAttributes = pgTable("product_attributes", {
  id: id(),
  productId: uuid("product_id").notNull().references(() => products.id, { onDelete: "cascade" }),
  name: text("name").notNull(),
  value: text("value").notNull(),
}, (t) => [index("attrs_product_idx").on(t.productId)]);

export const productTags = pgTable("product_tags", {
  productId: uuid("product_id").notNull().references(() => products.id, { onDelete: "cascade" }),
  tag: text("tag").notNull(),
}, (t) => [primaryKey({ columns: [t.productId, t.tag] })]);

export const productCollections = pgTable("product_collections", {
  id: id(),
  slug: text("slug").notNull().unique(),
  name: text("name").notNull(),
  description: text("description"),
  isActive: boolean("is_active").notNull().default(true),
  createdAt: createdAt(),
});

export const collectionProducts = pgTable("collection_products", {
  collectionId: uuid("collection_id").notNull().references(() => productCollections.id, { onDelete: "cascade" }),
  productId: uuid("product_id").notNull().references(() => products.id, { onDelete: "cascade" }),
  sortOrder: integer("sort_order").notNull().default(0),
}, (t) => [primaryKey({ columns: [t.collectionId, t.productId] })]);
